// Filter: CVR leads with email, not yet emailed
const items = $input.all();
const filtered = items.filter(item => {
  const d = item.json;
  const fuente = (d.Fuente || '').toLowerCase().trim();
  const email = (d.Email || '').trim();
  const estado = (d.Estado || '').toLowerCase().trim();
  return fuente === 'cvr' && email.includes('@') && estado === 'nuevo';
});

// Limit to 25 per day
const limited = filtered.slice(0, 25);

if (limited.length === 0) {
  // Return empty to stop the workflow gracefully
  return [];
}

return limited;

// ── Sector detection from Industry (branche) text ──
const BRANCHE_MAP = {
