// ── Detect sector from branche text ──
function detectSector(industry) {
  const lower = (industry || '').toLowerCase();
  for (const [keyword, sector] of Object.entries(BRANCHE_MAP)) {
    if (lower.includes(keyword)) return sector;
  }
  return 'revision'; // fallback
}

