    <a href="mailto:jmconsultingsai@gmail.com?subject=Unsubscribe&body=Please%20remove%20me%20from%20your%20mailing%20list.%20Company:%20${encodeURIComponent(companyName)}" style="color:#3366cc;text-decoration:underline;">Unsubscribe</a>
