// ── Process current item ──
const item = $input.first();
const empresa = (item.json.Empresa || '').trim();
const email = (item.json.Email || '').trim();
const industry = (item.json.Industry || '').trim();

const sector = detectSector(industry);
const config = SECTORS[sector] || SECTORS.revision;
const html = buildEmail(empresa, sector);

return [{
  json: {
    ...item.json,
    _sector: sector,
    _subject: config.subject,
    _htmlBody: html,
    _to: email,
    _empresa: empresa,
  }
}];
